import 'package:flutter/material.dart';import '../../Features/Main/presentation/pages/main_screen.dart';import 'route_name.dart';class AppRoutes {  static Route<dynamic> generateRoute(RouteSettings settings) {    switch (settings.name) {      // case AppRouteNames.splash:      //   return MaterialPageRoute(builder: (_) => const SplashScreen());      // case AppRouteNames.boarding:      //   return MaterialPageRoute(builder: (_) => const BoardingScreen());      // case AppRouteNames.start:      //   return MaterialPageRoute(builder: (_) => const AuthenticationScreen());      case AppRouteNames.main:        return MaterialPageRoute(builder: (_) => const MainScreen());      default:        return MaterialPageRoute(          builder: (_) => Scaffold(            body: Center(              child: Text(                  'No route defined for "${settings.name?.split("/").last}" '),            ),          ),        );    }  }}